 static Material Mat(string n,Color c,float emission=0){var m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=c;m.SetFloat("_Smoothness",.15f);if(emission>0){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*emission);}AssetDatabase.CreateAsset(m,Dir+"/"+n+".mat");return m;}
 static GameObject Box(string n,Vector3 p,Vector3 s,Material m,Transform parent=null,bool collider=true){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(parent?parent:root,false);g.transform.position=p;g.transform.localScale=s;g.GetComponent<Renderer>().sharedMaterial=m;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());return g;}
 static void Beam(string n,Vector3 a,Vector3 b,float width,Material m,Transform p=null,bool collider=true){var g=Box(n,(a+b)/2,new Vector3(width,width,Vector3.Distance(a,b)),m,p,collider);g.transform.rotation=Quaternion.LookRotation(b-a);}
