 static float Distance(Vector3 p){float best=1000;for(int i=1;i<route.Length;i++){var a=route[i-1];var d=route[i]-a;best=Mathf.Min(best,Vector3.Distance(p,a+d*Mathf.Clamp01(Vector3.Dot(p-a,d)/d.sqrMagnitude)));}return best;}
