 static void Fence(Vector3 a,Vector3 b,Transform p){float len=Vector3.Distance(a,b);int count=Mathf.CeilToInt(len/2.8f);for(int i=0;i<=count;i++){var pos=Vector3.Lerp(a,b,i/(float)count);pos.y=Height(pos.x,pos.z);Box("Fence_Post",pos+Vector3.up*1.25f,new Vector3(.12f,2.5f,.12f),steel,p);}var dir=(b-a).normalized;for(int i=0;i<count;i++){var s=Vector3.Lerp(a,b,i/(float)count);var e=Vector3.Lerp(a,b,(i+1f)/count);s.y=Height(s.x,s.z);e.y=Height(e.x,e.z);Beam("Fence_Rail",s+Vector3.up*.35f,e+Vector3.up*.35f,.045f,steel,p,false);Beam("Fence_Rail",s+Vector3.up*2.2f,e+Vector3.up*2.2f,.045f,steel,p,false);for(int k=0;k<7;k++){float u=(k+.5f)/7;var c=Vector3.Lerp(s,e,u);Beam("Wire",c+Vector3.up*.35f,c+Vector3.up*2.2f,.018f,steel,p,false);}Beam("Fence_Diagonal",s+Vector3.up*.35f,e+Vector3.up*2.2f,.025f,steel,p,false);var col=Group("Fence_Collision",p).gameObject;col.transform.position=(s+e)/2+Vector3.up*1.2f;col.transform.rotation=Quaternion.LookRotation(e-s);col.AddComponent<BoxCollider>().size=new Vector3(.08f,2.4f,Vector3.Distance(s,e));}}
