 static void Power(){var g=Group("05_Utility_Yard_NoPowerLogic");Box("Equipment_Pad",new Vector3(-5,-.02f,24),new Vector3(12,.15f,9),concrete,g);Fence(new Vector3(-11,0,19.5f),new Vector3(1,0,19.5f),g);Fence(new Vector3(1,0,19.5f),new Vector3(1,0,28.5f),g);Fence(new Vector3(1,0,28.5f),new Vector3(-11,0,28.5f),g);Fence(new Vector3(-11,0,19.5f),new Vector3(-11,0,24.5f),g);Fence(new Vector3(-11,0,27),new Vector3(-11,0,28.5f),g);Box("Transformer",new Vector3(-4,1.2f,23),new Vector3(3,2.2f,2),steel,g);for(int i=0;i<10;i++)Box("Cooling_Fin",new Vector3(-5.4f+i*.31f,1.1f,21.9f),new Vector3(.1f,1.7f,.4f),cream,g);for(int i=0;i<3;i++){Box("Insulator",new Vector3(-5+i,2.55f,23),new Vector3(.2f,.5f,.2f),cream,g);Beam("Busbar",new Vector3(-5+i,2.8f,23),new Vector3(-5+i,3.2f,22),.04f,steel,g);}Box("Distribution_Cabinet",new Vector3(-8,1.15f,23),new Vector3(1.5f,2.1f,.8f),cream,g);Sign("HIGH VOLTAGE\nISOLATED",new Vector3(-8,1.5f,22.55f),.08f,g,Quaternion.identity);for(int i=0;i<4;i++)Box("Vent",new Vector3(-8,.6f+i*.1f,22.55f),new Vector3(.8f,.025f,.03f),steel,g,false);}
 static Mesh Cone(string name,float radius,float height){var v=new List<Vector3>();var t=new List<int>();for(int i=0;i<7;i++){float a=i*Mathf.PI*2/7,b=(i+1)*Mathf.PI*2/7;int n=v.Count;v.AddRange(new[]{new Vector3(Mathf.Cos(a)*radius,0,Mathf.Sin(a)*radius),new Vector3(0,height,0),new Vector3(Mathf.Cos(b)*radius,0,Mathf.Sin(b)*radius)});t.AddRange(new[]{n,n+1,n+2});}return Mesh(name,v,t);}
 static void Forest(){var g=Group("06_Conifer_Forest");var crown=Cone("SevenSided_Pine_Crown",1,2.5f);UnityEngine.Random.InitState(8117);int placed=0;for(int i=0;i<800;i++){float x=UnityEngine.Random.Range(-65,5),z=UnityEngine.Random.Range(2,79);if(Distance(new Vector3(x,0,z))<5.5f||(x>-25&&z>16&&z<53)||Vector2.Distance(new Vector2(x,z),new Vector2(-28.5f,34))<4)continue;if(g.Cast<Transform>().Any(q=>Vector2.Distance(new Vector2(q.position.x,q.position.z),new Vector2(x,z))<2.5f))continue;var tree=Group("Pine_"+(placed++).ToString("D3"),g);tree.position=new Vector3(x,Height(x,z),z);float height=UnityEngine.Random.Range(7,13);var trunk=GameObject.CreatePrimitive(PrimitiveType.Cylinder);trunk.name="Trunk";trunk.transform.SetParent(tree,false);trunk.transform.localPosition=Vector3.up*height*.38f;trunk.transform.localScale=new Vector3(.25f,height*.38f,.25f);trunk.GetComponent<Renderer>().sharedMaterial=bark;for(int j=0;j<3;j++){var c=Surface("Crown_"+j,crown,j%2==0?leaf:leaf2,tree,false);c.transform.localPosition=Vector3.up*(height*.22f+j*height*.18f);float w=(1.7f-j*.35f)*UnityEngine.Random.Range(.85f,1.15f);c.transform.localScale=new Vector3(w,height*.14f,w);c.transform.localRotation=Quaternion.Euler(0,UnityEngine.Random.Range(0,360),0);}}
 var boundary=Group("07_Perimeter_Fence");Fence(new Vector3(-50,0,14),new Vector3(-50,0,52),boundary);Fence(new Vector3(-50,0,14),new Vector3(5,0,14),boundary);Fence(new Vector3(-50,0,52),new Vector3(5,0,52),boundary);Fence(new Vector3(5,0,14),new Vector3(5,0,34),boundary);Fence(new Vector3(5,0,44),new Vector3(5,0,52),boundary);
 var rocks=Group("08_Rocks_And_GroundCover");for(int i=0;i<60;i++){float x=UnityEngine.Random.Range(-49,3),z=UnityEngine.Random.Range(14,52);if(Distance(new Vector3(x,0,z))<4.5f||(x>-25&&z>17&&z<50))continue;var rock=GameObject.CreatePrimitive(PrimitiveType.Sphere);rock.name="Stone";rock.transform.SetParent(rocks,false);rock.transform.position=new Vector3(x,Height(x,z),z);rock.transform.localScale=new Vector3(UnityEngine.Random.Range(.5f,1.7f),UnityEngine.Random.Range(.3f,.9f),UnityEngine.Random.Range(.5f,1.4f));rock.GetComponent<Renderer>().sharedMaterial=concrete;}}
 static void Facade(){var g=Group("09_Entry_Facade_Accents");Box("Entrance_Canopy",new Vector3(4.7f,3.3f,39),new Vector3(2.5f,.2f,5),steel,g);foreach(float z in new[]{36.6f,41.4f})Box("Canopy_Column",new Vector3(3.6f,1.6f,z),new Vector3(.13f,3.2f,.13f),steel,g);Box("Entry_Nameplate",new Vector3(5.82f,3.8f,39),new Vector3(.06f,.7f,5.8f),steel,g,false);Sign("NORTH / RESEARCH STATION",new Vector3(5.77f,3.8f,39),.12f,g,Quaternion.Euler(0,90,0));foreach(float z in new[]{35.4f,43f}){Box("Facade_WindowFrame",new Vector3(5.85f,2,z),new Vector3(.08f,1,1.7f),steel,g,false);Box("Facade_Opaque_Glass",new Vector3(5.79f,2,z),new Vector3(.04f,.8f,1.5f),glass,g,false);}Lamp(new Vector3(2,0,43),g);}
 [MenuItem("Tools/Station/Assemble Exterior v1")] public static void Build(){if(File.Exists(ScenePath))throw new Exception("Output already exists; refusing overwrite.");var s=Application.isBatchMode?EditorSceneManager.OpenScene("Assets/LevelDesign/Station/Greybox/StationGreybox.unity"):UnityEngine.SceneManagement.SceneManager.GetActiveScene(); if(s.path!="Assets/LevelDesign/Station/Greybox/StationGreybox.unity")throw new Exception("Open the station scene first.");var all=UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsInactive.Include,FindObjectsSortMode.None);var spawn=all.Single(t=>t.name=="StationPlayerSpawn");if(Vector3.Distance(spawn.position,route[0])>.1f)throw new Exception("Spawn moved; inspect scene.");var old=all.Single(t=>t.name=="Exterior_Approach");var station=all.Single(t=>t.name=="STATION_GREYBOX_GENERATED");if(station.position!=Vector3.zero||station.lossyScale!=Vector3.one)throw new Exception("Station transformed.");root=new GameObject("STATION_EXTERIOR").transform;
 earth=Mat("Forest_Soil",new Color(.19f,.23f,.16f));gravel=Mat("Gravel",new Color(.32f,.31f,.27f));asphalt=Mat("Asphalt",new Color(.16f,.19f,.2f));concrete=Mat("Concrete",new Color(.42f,.44f,.4f));steel=Mat("Painted_Steel",new Color(.16f,.22f,.22f));bark=Mat("Bark",new Color(.22f,.17f,.12f));leaf=Mat("Pine_Dark",new Color(.1f,.2f,.16f));leaf2=Mat("Pine_Light",new Color(.16f,.27f,.21f));cream=Mat("Weathered_Cladding",new Color(.57f,.59f,.5f));glass=Mat("Dark_Glass",new Color(.14f,.23f,.25f));red=Mat("Barrier_Red",new Color(.65f,.18f,.12f));amber=Mat("Emergency_Warm",new Color(1,.65f,.28f),2);
 Ground();Road();Checkpoint();Sensor();Power();Forest();Facade();old.gameObject.SetActive(false);
 var players=UnityEngine.Object.FindObjectsByType<CharacterController>(FindObjectsSortMode.None);if(players.Length!=1)throw new Exception("Expected one existing player.");var player=players[0];player.transform.position=spawn.position+Vector3.up*(player.height/2-player.center.y+.04f);player.transform.rotation=Quaternion.LookRotation(route[1]-route[0]);
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s,ScenePath);Validate();Render();Debug.Log("EXTERIOR_BUILD_SUCCESS");}
 public static void Validate(){var report=new List<string>();Physics.SyncTransforms();var player=UnityEngine.Object.FindFirstObjectByType<CharacterController>();var p0=player.transform.position;bool enabled=player.enabled;player.enabled=false;int samples=0;for(int j=1;j<route.Length;j++)for(int i=0;i<=100;i++){var p=Vector3.Lerp(route[j-1],route[j],i/100f);if(!Physics.Raycast(p+Vector3.up*.3f,Vector3.down,out var hit,.7f))throw new Exception("Ground hole "+p);if(Physics.CheckCapsule(hit.point+Vector3.up*.4f,hit.point+Vector3.up*1.72f,.32f))throw new Exception("Blocked route "+p);samples++;}foreach(var p in new[]{new Vector3(-28.5f,0,32.8f),new Vector3(-18.8f,0,38.5f),new Vector3(-12,0,26),new Vector3(-8,0,26)}){if(!Physics.Raycast(p+Vector3.up*.5f,Vector3.down,1)||Physics.CheckCapsule(p+Vector3.up*.4f,p+Vector3.up*1.72f,.32f))throw new Exception("Blocked service point "+p);}player.enabled=enabled;report.Add("PASS: "+samples+" route samples, floor and 2m capsule clearance; sensor, booth approach and utility entrance clear.");report.Add("Existing player repositioned to original exterior spawn; controller settings unchanged.");report.Add("Not a Play Mode walkthrough. Original interior and manual laboratory retained in copied scene.");File.WriteAllLines(Dir+"/Validation.txt",report);}
 static void Capture(Vector3 pos,Vector3 target,string name){var body=UnityEngine.Object.FindFirstObjectByType<CharacterController>().GetComponent<Renderer>(); bool was=body && body.enabled; if(body)body.enabled=false;var g=new GameObject("Temporary_Review_Camera");var c=g.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.fieldOfView=65;c.nearClipPlane=.1f;c.farClipPlane=200;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.31f,.38f,.45f);var rt=new RenderTexture(1600,900,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1600,900,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,900),0,0);tex.Apply();File.WriteAllBytes("work/exterior/"+name+".png",tex.EncodeToPNG());RenderTexture.active=null;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(g);if(body)body.enabled=was;}
 public static void Render(){Capture(new Vector3(-44,1.7f,22),new Vector3(-17,2,34),"spawn");Capture(new Vector3(-30,6,29),new Vector3(-6,1,34),"overview");}
