 static ExteriorAssembly(){EditorApplication.playModeStateChanged+=OnPlay;}
 static int waypoint; static double started; static CharacterController walker;
 [MenuItem("Tools/Station/Finalize and Test Exterior")]
 public static void FinalizeExterior(){
 var ext=GameObject.Find("STATION_EXTERIOR"); if(!ext)throw new Exception("Exterior missing");
 foreach(var text in ext.GetComponentsInChildren<TextMesh>())text.gameObject.SetActive(false);
 foreach(var light in ext.GetComponentsInChildren<Light>())light.shadows=LightShadows.None;
 FinishSurface();Validate();Render();EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());
 SessionState.SetBool("ExteriorWalk",true); EditorApplication.isPlaying=true;
 }
 static void OnPlay(PlayModeStateChange state){if(state==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("ExteriorWalk",false)){waypoint=1;started=EditorApplication.timeSinceStartup;walker=UnityEngine.Object.FindFirstObjectByType<CharacterController>();EditorApplication.update+=WalkTick;}if(state==PlayModeStateChange.ExitingPlayMode){EditorApplication.update-=WalkTick;}}
 static void WalkTick(){if(!EditorApplication.isPlaying||!walker)return;var target=waypoint<route.Length?route[waypoint]:new Vector3(9,0,39);var d=target-walker.transform.position;d.y=0;
 if(walker.transform.position.y < -.5f || EditorApplication.timeSinceStartup-started>60){FinishWalk("FAIL automatic Play Mode traversal at "+walker.transform.position);return;}
 if(d.magnitude<.6f){waypoint++;if(waypoint>route.Length){FinishWalk("PASS Play Mode: existing PlayerController driven with W input and scripted heading traversed spawn, checkpoint and station entrance. No controller settings changed.");return;}target=waypoint<route.Length?route[waypoint]:new Vector3(9,0,39);d=target-walker.transform.position;d.y=0;}
 walker.transform.rotation=Quaternion.LookRotation(d);var kb=UnityEngine.InputSystem.Keyboard.current;if(kb!=null)UnityEngine.InputSystem.InputSystem.QueueStateEvent(kb,new UnityEngine.InputSystem.LowLevel.KeyboardState(UnityEngine.InputSystem.Key.W));
 }
 static void FinishWalk(string result){EditorApplication.update-=WalkTick;SessionState.SetBool("ExteriorWalk",false);var kb=UnityEngine.InputSystem.Keyboard.current;if(kb!=null)UnityEngine.InputSystem.InputSystem.QueueStateEvent(kb,new UnityEngine.InputSystem.LowLevel.KeyboardState());File.WriteAllText(Dir+"/PlayModeValidation.txt",result);Debug.Log(result);EditorApplication.isPlaying=false;} static Vector3 Edge(int i){var n0=Vector3.Cross(Vector3.up,route[Mathf.Min(i+1,route.Length-1)]-route[Mathf.Max(i-1,0)]).normalized;var seg=Vector3.Cross(Vector3.up,route[Mathf.Min(i+1,route.Length-1)]-route[i==route.Length-1?i-1:i]).normalized;return n0/Mathf.Max(.7f,Vector3.Dot(n0,seg));}
 static void FinishSurface(){var road=GameObject.Find("STATION_EXTERIOR").transform.Find("02_Road");foreach(Transform t in road){if(t.name=="TurnBlend")t.gameObject.SetActive(false);if(t.name=="Entry_Apron")t.position=new Vector3(-.5f,-.02f,39);if(t.name=="Apron_Joint"){var p=t.position;p.y=.046f;t.position=p;}}
 for(int i=1;i<route.Length;i++)foreach(float w in new[]{5.4f,4f}){var t=road.Find((w>5?"Shoulder_":"Road_")+i);var m=t.GetComponent<MeshFilter>().sharedMesh;var a=route[i-1];var b=route[i];var na=Edge(i-1);var nb=Edge(i);var v=new[]{a-na*w/2,b-nb*w/2,b+nb*w/2,a+na*w/2};for(int j=0;j<4;j++)v[j]+=Vector3.up*(w>5?-.035f:-.015f);m.vertices=v;m.RecalculateBounds();m.RecalculateNormals();EditorUtility.SetDirty(m);var mc=t.GetComponent<MeshCollider>();mc.sharedMesh=null;mc.sharedMesh=m;}AssetDatabase.SaveAssets();}}
